      berikut: R.berikut,
      bacaan: A.bacaan || [],
      tangga: A.tangga || [],
      skenario: (A.skenario || []).map(s => ({ tahap: s.tahap, nama: s.nama, jika: s.jika, maka: s.maka, kelas: s.kelas })),
      kesimpulan: A.kesimpulan,
